class Manager:
    def __init__(self, root, limits):
        self.root, self.limits = root, limits
        self.thread = None
        self.key = None
        self.errors = {}
        self.mutex = threading.Lock()

    def start(self, key):
        with self.mutex:
            if self.thread and self.thread.is_alive():
                if self.key == key:
                    return
                raise ResourceError("Another request is active; this request remains pending")
            self.key = key

            def run():
                try:
                    job.run(self.root, self.limits, key)
                except (InputError, OSError, ValueError, RuntimeError) as exc:
                    self.errors[key] = dict(
                        message=str(exc),
                        error_type=type(exc).__name__,
                        observed_process="stopped",
                        persistence_failure=isinstance(exc, PersistenceError),
                    )

            self.thread = threading.Thread(target=run, name="d01-coordinator", daemon=False)
            self.thread.start()

    def stop(self):
        if self.thread and self.thread.is_alive():
            api.cancel(self.root, self.key, hashlib.sha256(secrets.token_bytes(32)).hexdigest())
            self.thread.join(125)


def make_server(root, limits, port=8774):
    if not 1024 <= port <= 65535:
        raise InputError("D01 port must be 1024..65535")
    owner = Context(root)
    manager = Manager(owner.root, limits)
    token = secrets.token_urlsafe(32)
    origin = "http://127.0.0.1:" + str(port)

    class Handler(BaseHTTPRequestHandler):
        protocol_version = "HTTP/1.1"

        def host_ok(self):
            if self.headers.get("Host") != "127.0.0.1:" + str(port):
                raise InputError("D01 untrusted Host; use " + origin)
            if self.headers.get("Sec-Fetch-Site") == "cross-site":
                raise InputError("D01 cross-origin request refused")

        def send_json(self, value, status=200):
            raw = json.dumps(value, allow_nan=False).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(raw)))
            self.headers_common()
            self.end_headers()
            self.wfile.write(raw)

        def headers_common(self):
            self.send_header("Cache-Control", "no-store")
            self.send_header("X-Content-Type-Options", "nosniff")
            self.send_header("Referrer-Policy", "no-referrer")
            inline = " 'unsafe-inline'" if self.path.startswith("/historical/") else ""
            self.send_header(
                "Content-Security-Policy",
                "default-src 'self'; script-src 'self'"
                + inline
                + "; style-src 'self'"
                + inline
                + "; "
                "img-src 'self' data:; media-src 'self'; connect-src 'self'; "
                "frame-ancestors 'none'; base-uri 'none'",
            )

        def target(self):
            path = unquote(urlsplit(self.path).path)
            if any(p in {".", ".."} for p in path.split("/")) or "\\" in path or "%" in path:
                raise InputError("D01 path traversal/encoded path refused")
            return path

        def send_file(self, path, mime):
            size = path.stat().st_size
            try:
                first, last, partial = byte_range(self.headers.get("Range"), size)
            except InputError:
                self.send_response(416)
                self.send_header("Content-Range", f"bytes */{size}")
                self.send_header("Content-Length", "0")
                self.end_headers()
                return
            self.send_response(206 if partial else 200)
            self.send_header("Content-Type", mime)
            self.send_header("Content-Length", str(last - first + 1))
            self.send_header("Accept-Ranges", "bytes")
            if partial:
                self.send_header("Content-Range", f"bytes {first}-{last}/{size}")
            self.headers_common()
            self.end_headers()
            if self.command == "HEAD":
                return
            with path.open("rb") as stream:
                stream.seek(first)
                remaining = last - first + 1
                while remaining:
                    block = stream.read(min(131072, remaining))
                    if not block:
                        raise InputError("D01 authorized media changed while streaming")
                    self.wfile.write(block)
                    remaining -= len(block)

        def do_HEAD(self):
            self.do_GET()

        def do_GET(self):
            try:
                self.host_ok()
                path = self.target()
                assets = {
                    "/": ("index.html", "text/html; charset=utf-8"),
                    "/app.js": ("app.js", "text/javascript; charset=utf-8"),
                    "/style.css": ("style.css", "text/css; charset=utf-8"),
                }
                if path in assets:
                    name, mime = assets[path]
                    return self.send_file(STATIC / name, mime)
                if path == "/api/bootstrap":
                    return self.send_json(
                        dict(token=token, catalogue=api.catalogue(root), library=api.library(root))
                    )
                if path.startswith("/api/job/"):
                    key = api.identifier(path[9:])
                    value = api.status(root, key)
                    if key in manager.errors:
                        value["observed_failure"] = manager.errors[key]
                    return self.send_json(value)
                if path.startswith("/api/result/"):
                    return self.send_json(api.result(root, api.identifier(path[12:])))
                if path.startswith("/api/revision/"):
                    return self.send_json(queries.exact_revision(owner, api.identifier(path[14:])))
                if path.startswith("/api/waveform/"):
                    value = record(
                        owner.directory / "waveforms" / (api.identifier(path[14:]) + ".json")
                    )
                    return self.send_json(value)
                if path.startswith("/media/"):
                    target, _ = media.validate(owner, api.identifier(path[7:]))
                    return self.send_file(target, "audio/wav")
                if path.startswith("/historical/"):
                    from ..refinement.context import Context as HistoricalContext

                    view = HistoricalContext(root)
                    locator = record(view.directory / "report.json")
                    bundle = contained(root / locator["bundle"], view.reports).parent
                    allowed = verify_bundle(root, bundle, view.reports)
                    if (
                        record(bundle / "bundle.json")["record_hash"]
                        != owner.protocol["playback_bundle"]
                    ):
                        raise InputError("D01 pinned historical report changed")
                    key = "/" + path[len("/historical/") :]
                    if key == "/":
                        key = "/index.html"
                    if key not in allowed:
                        raise FileNotFoundError("Outside historical bundle allowlist")
                    return self.send_file(
                        allowed[key],
                        "audio/wav" if key.endswith(".wav") else "text/html; charset=utf-8",
                    )
                raise FileNotFoundError("Outside application/media allowlist")
            except (BrokenPipeError, ConnectionResetError):
                return
            except (InputError, OSError, ValueError, KeyError) as exc:
                self.send_json(
                    dict(error=str(exc), error_type=type(exc).__name__),
                    404 if isinstance(exc, FileNotFoundError) else 409,
                )
            except (BrokenPipeError, ConnectionResetError):
                return

        def do_POST(self):
            try:
                self.host_ok()
                if self.headers.get("Origin") != origin or not secrets.compare_digest(
                    self.headers.get("X-D01-Token", ""), token
                ):
                    self.close_connection = True
                    rejected_length = self.headers.get("Content-Length", "")
                    if rejected_length.isdecimal() and int(rejected_length) <= 65536:
                        self.connection.settimeout(5)
                        self.rfile.read(int(rejected_length))
                    return self.send_json(
                        dict(error="Untrusted origin/session; refresh this local application"), 403
                    )
                length = self.headers.get("Content-Length", "")
                if (
                    not length.isascii()
                    or not length.isdecimal()
                    or self.headers.get("Transfer-Encoding")
                ):
                    raise InputError("D01 bounded Content-Length required")
                length = int(length)
                path = self.target()
                if path == "/api/upload":
                    return self.upload(length)
                if self.headers.get_content_type() != "application/json" or not 0 < length <= 65536:
                    raise InputError("D01 JSON request must be 1..65536 bytes")
                request = json.loads(self.rfile.read(length))
                if path == "/api/submit":
                    result = api.submit(root, limits, request)
                    try:
                        manager.start(result["job_id"])
                    except ResourceError:
                        result["pending_reason"] = "Another request is active; resume when it stops"
                    return self.send_json(result, 202)
                if path in {"/api/cancel", "/api/resume"}:
                    if set(request) != {"job_id", "request_id"}:
                        raise InputError("D01 control requires job and idempotent request ID")
                    key = api.identifier(request["job_id"])
                    if path == "/api/cancel":
                        return self.send_json(api.cancel(root, key, request["request_id"]))
                    result = api.resume_control(root, key, request["request_id"])
                    manager.start(key)
                    return self.send_json(result, 202)
                raise FileNotFoundError("Unknown explicit application mutation")
            except (InputError, OSError, ValueError, KeyError) as exc:
                self.close_connection = True
                self.send_json(dict(error=str(exc), error_type=type(exc).__name__), 409)
            except (BrokenPipeError, ConnectionResetError):
                return

        def upload(self, length):
            if self.headers.get_content_type() != "application/octet-stream":
                raise InputError("D01 upload requires audio bytes")
            from ..inputs import SUPPORTED
            from ..resources import CatalogueBudget

            label = unquote(self.headers.get("X-Filename", "reference"))
            suffix = Path(label).suffix.lower()
            if suffix not in SUPPORTED or len(label) > 160 or any(ord(c) < 32 for c in label):
                raise InputError("D01 unsupported filename/format; select WAV, FLAC, AIFF or MP3")
            if not 0 < length <= min(limits["max_input_bytes"], 128 * 1024**2):
                raise ResourceError("D01 upload exceeds bounded import/input allowance")
            key = api.identifier(self.headers.get("X-Upload-ID"))
            if len(list((owner.directory / "uploads").glob("*.json"))) >= 64:
                raise ResourceError("D01 upload count exhausted; load an existing reference")
            allocation = "upload-" + key
            context = Context(root, allocation)
            existing = context.directory / "uploads" / (key + ".json")
            if existing.exists():
                raise InputError("D01 upload already exists; load the registered reference")
            context.admit(allocation, 512 * 1024)
            budget = CatalogueBudget(root, limits)
            context.charge(budget, import_bytes=length)
            budget.reserve(length + 4096)
            target = context.audio / "imports" / (key + suffix)
            target.parent.mkdir(parents=True, exist_ok=True)
            h = hashlib.sha256()
            # Never overwrite: exclusive mode retains interrupted imports for diagnosis.
            with target.open("xb") as stream:
                remaining = length
                while remaining:
                    block = self.rfile.read(min(131072, remaining))
                    if not block:
                        raise InputError("D01 truncated upload; retained incomplete import")
                    stream.write(block)
                    h.update(block)
                    remaining -= len(block)
                stream.flush()
                os.fsync(stream.fileno())
            context.publish(
                budget,
                existing,
                dict(
                    upload_id=key,
                    path=target.relative_to(root).as_posix(),
                    sha256=h.hexdigest(),
                    bytes=length,
                    label=label,
                ),
                immutable=True,
            )
            context.release(allocation)
            self.send_json(dict(upload_id=key, label=label, bytes=length), 201)

        def log_message(self, *args):
            pass

    try:
        server = ThreadingHTTPServer(("127.0.0.1", port), Handler)
    except OSError as exc:
        raise InputError(f"D01 cannot bind {origin}; port is in use or unavailable: {exc}") from exc
    server.manager = manager
    server.daemon_threads = True
    return server


def serve(root, limits, port=8774):
    from ..matchers.runner import peak_memory

    with lock(root, "server"):
        server = make_server(root, limits, port)
        print(
            f"Sound Search: http://127.0.0.1:{port}/ · foreground PID {os.getpid()} · Ctrl+C stops",
            flush=True,
        )
        print(
            f"Server initial peak working memory: {peak_memory()} bytes "
            "(worker overlap reported separately)",
            flush=True,
        )
        try:
            server.serve_forever(poll_interval=0.25)
        except KeyboardInterrupt:
            print("Stopping admission; waiting for the owned bounded worker…", flush=True)
        finally:
            server.server_close()
            server.manager.stop()

original_sources.application/job.py:
"""Serial bounded worker orchestration, immutable unit commits and protected settlement."""

import json
import os
import subprocess
import time
import uuid

from ..evaluation.artifacts import record
from ..resources import CatalogueBudget
from ..storage import InputError, ResourceError, digest, project_lock
from . import api, history, media, pipeline, queries
from .context import Context, PersistenceError
from .locks import lock


def unit_path(owner, key, unit):
    return owner.directory / "units" / key / (digest(unit) + ".json")


def units(owner, value):
    request = value["identity"]["request"]
    if request["kind"] not in {"search", "validate"}:
        return [request["kind"]]
    old = history.inputs(owner)[1]
    count = len(old["input"]["sources"])
    return [
        "query",
        *[
            "source:" + s["recording_id"]
            for s in sorted(old["input"]["sources"], key=lambda s: s["recording_id"])
        ],
        *["aggregate:" + str(i) for i in range((count * 2 + 7) // 8)],
        "aggregate-final",
        *(["chain"] if request["input"]["query"].get("historical") else []),
        *["media:" + str(i) for i in range(5)],
        "publish",
    ]


def committed(owner, key, unit):
    path = unit_path(owner, key, unit)
    if not path.exists():
        return None
    value = record(path)
    if value["job_id"] != key or value["unit"] != unit:
        raise InputError("D01 committed unit/dependency mismatch")
    return value["output"]


def perform(budget, owner, value, unit, query_cache):
    request = value["identity"]["request"]
    spec, key = request["input"], value["job_id"]
    if request["kind"] == "register":
        from .server import upload_path

        return queries.register(budget, owner, upload_path(owner, spec["upload_id"]), spec["label"])
    if request["kind"] == "copy-reference":
        return queries.copy_historical(budget, owner, spec["revision"])
    if request["kind"] == "metadata-preflight":
        owner.charge(budget, metadata_bytes=128 * 1024)
        return pipeline.metadata_preflight(budget, owner)
    if request["kind"] == "native-qa":
        from .validation import native

        return native(budget, owner, spec)
    if request["kind"] == "save":
        return queries.save(budget, owner, spec)
    if request["kind"] == "rename":
        return queries.rename(budget, owner, spec)
    if request["kind"] == "preview":
        source = media.source_for_asset(owner, spec["asset_id"])
        from ..queries.assets import read_asset

        _, _, samples = read_asset(
            budget, queries.QueryOwner(owner), spec["asset_id"], with_samples=True
        )
        return dict(media=media.cached_clip(budget, owner, source, spec["bounds"], samples))
    if "query" not in query_cache:
        selection = dict(spec["query"])
        previous_query = committed(owner, key, "query")
        if previous_query is not None:
            saved = owner.get(previous_query["query"], "queries")
            selection["materialization"] = saved["materialization"]
        query_cache["query"] = queries.load(budget, owner, selection)
    q, matrix = query_cache["query"]
    if unit == "query":
        return dict(query=owner.put(budget, "queries", q), new_encodes=q["new_encodes"])
    if unit.startswith("source:"):
        return pipeline.source_unit(budget, owner, spec, unit[7:], q, matrix)
    source_results = {
        u[7:]: committed(owner, key, u) for u in units(owner, value) if u.startswith("source:")
    }
    if unit.startswith("aggregate:") or unit == "aggregate-final":
        if "aggregate" not in query_cache:
            query_cache["aggregate"] = pipeline.aggregate(budget, owner, spec, source_results, q)
        result, capture = query_cache["aggregate"]
        if unit == "aggregate-final":
            # All group/source/snapshot refs must exist before publishing this root.
            for path, (kind, data) in capture.records.items():
                ref = dict(path=path, record_hash=__import__("pathlib").Path(path).stem)
                owner.get(ref, kind)
            return dict(aggregate=owner.put(budget, "aggregates", result))
        i = int(unit.split(":")[1]) * 8
        items = sorted(capture.records.items())
        # Sources/snapshot are small shared records. Groups are the bounded subunits.
        groups = [(path, item) for path, item in items if item[0] == "group-results"]
        for path, (kind, data) in [(p, v) for p, v in items if v[0] != "group-results"] + groups[
            i : i + 8
        ]:
            owner.put(budget, kind, data)
        return dict(groups=[p for p, _ in groups[i : i + 8]], new_encodes=0)
    aggregate = owner.get(committed(owner, key, "aggregate-final")["aggregate"], "aggregates")
    if unit == "chain":
        return dict(
            chain=owner.put(
                budget, "chains", pipeline.audit_chain(budget, owner, spec, aggregate, q)
            )
        )
    if unit.startswith("media:"):
        # C03 experimental rendering is explicitly separate from legacy/event cards.
        if spec["arm"] == "historical-refinement":
            return dict(cards=[], historical=True)
        return dict(cards=media.cards(budget, owner, aggregate, int(unit[6:]) * 2, 2))
    if unit == "publish":
        cards = [c for i in range(5) for c in committed(owner, key, "media:" + str(i))["cards"]]
        chain = committed(owner, key, "chain") if spec["query"].get("historical") else None
        return dict(
            result=owner.put(
                budget,
                "results",
                dict(
                    schema_version="d01-result-1",
                    state="complete",
                    job_id=key,
                    query=committed(owner, key, "query")["query"],
                    selection=spec["query"],
                    policy=spec["arm"],
                    consumer=value["consumer"],
                    **aggregate,
                    cards=cards,
                    chain=chain,
                    historical_view=spec["arm"] == "historical-refinement",
                    resource_owner="data/runs/application/pool.json",
                    historical_c04_state="partial 145/148",
                    new_catalogue_encodes=0,
                    defaults=dict(audio="original", arm="legacy-mean", pitch="off"),
                ),
            )
        )
    raise InputError("D01 unknown executable unit")


def worker(request):
    from ..matchers.job import offline_network
    from ..matchers.runner import memory_check

    owner = Context(__import__("pathlib").Path(request["root"]), request["job_id"])
    budget = CatalogueBudget(owner.root, request["limits"])
    key = request["job_id"]
    with project_lock(owner.root), lock(owner.root, "worker"), offline_network():
        value = api.job(owner, key)
        if history.consumer(owner) != value["consumer"] and not history.compatible(
            owner, value["consumer"]
        ):
            raise InputError("D01 request consumer changed; declare scoped compatibility")
        graph = units(owner, value)
        cache, done, encodes = {}, [], 0
        if request.get("finalization_audit"):
            from .validation import finalization

            receipt = finalization(budget, owner, key)
            return dict(
                status="ok",
                state="validated-finalization",
                completed=[],
                new_encodes=0,
                receipt=receipt,
                peak_working_bytes=memory_check(budget),
            )
        if request.get("validate_units"):
            spec = value["identity"]["request"]["input"]
            saved = owner.get(committed(owner, key, "query")["query"], "queries")
            q, matrix = queries.load(
                budget, owner, {**spec["query"], "materialization": saved["materialization"]}
            )
            for unit in request["validate_units"]:
                cancel = owner.directory / "cancels" / (key + ".json")
                if cancel.exists() and not record(cancel).get("resumed", False):
                    return dict(status="ok", state="cancelled", completed=[], new_encodes=0)
                answer = pipeline.source_unit(budget, owner, spec, unit[7:], q, matrix)
                validate_resumed(owner, budget, unit, committed(owner, key, unit), answer)
            return dict(
                status="ok",
                state="validated",
                completed=[],
                new_encodes=0,
                peak_working_bytes=memory_check(budget),
            )
        # Four useful units maximum. The worker owns one lazy model and query matrix.
        for unit in graph:
            if committed(owner, key, unit) is not None:
                continue
            cancel = owner.directory / "cancels" / (key + ".json")
            if cancel.exists() and not record(cancel).get("resumed", False):
                return dict(
                    status="ok",
                    state="cancelled",
                    completed=done,
                    new_encodes=encodes,
                    peak_working_bytes=memory_check(budget),
                )
            answer = perform(budget, owner, value, unit, cache)
            owner.publish(
                budget,
                unit_path(owner, key, unit),
                dict(job_id=key, unit=unit, output=answer),
                immutable=True,
            )
            done.append(unit)
            encodes += answer.get("new_encodes", 0)
            if len(done) >= 4 or time.monotonic() - budget.started > 60:
                break
        count = sum(unit_path(owner, key, u).exists() for u in graph)
        return dict(
            status="ok",
            state="complete" if count == len(graph) else "in_progress",
            completed=done,
            new_encodes=encodes,
            peak_working_bytes=memory_check(budget),
        )


def execute(owner, key, limits, validate_units=None, finalization_audit=False):
    from ..processing.runner import python_command

    environment = os.environ.copy()
    environment.update(
        OMP_NUM_THREADS="1", OPENBLAS_NUM_THREADS="1", MKL_NUM_THREADS="1", PYTHONIOENCODING="utf-8"
    )
    command = python_command(owner.root / "scripts/application-worker.py")
    request = dict(root=str(owner.root), job_id=key, limits=limits)
    if validate_units:
        request["validate_units"] = validate_units
    if finalization_audit:
        request["finalization_audit"] = True
    try:
        completed = subprocess.run(
            command,
            input=json.dumps(request),
            capture_output=True,
            text=True,
            encoding="utf-8",
            timeout=limits["max_seconds"],
            env=environment,
            check=False,
        )
    except subprocess.TimeoutExpired:
        return dict(
            status="failed",
            error_type="ResourceError",
            error="D01 actual worker exceeded 120s and stopped; retain reservation",
            uncertain=True,
        )
    try:
        result = json.loads(completed.stdout)
    except ValueError:
        return dict(
            status="failed",
            error_type="WorkerExit",
            error="D01 worker exited without a durable answer: " + completed.stderr[-1500:],
            uncertain=True,
        )
    return result


def reconcile(owner, key):
    """Only after exclusive coordinator/worker locks. Unobservable time stays charged."""
    pool = owner.pool()
    for identity, slot in pool["attempts"].items():
        if not slot["settled"]:
            previous_key = slot.get("job_id") or key
            previous = record(api.state_path(owner, previous_key))
            previous.update(
                state="interrupted",
                error=dict(
                    step="recovery",
                    message="Owned process stopped without settlement; full reservation retained",
                ),
            )
            owner.terminal(identity, api.state_path(owner, previous_key), previous, uncertain=True)


def _run(root, limits, key):
    owner = Context(root, key)
    # This lock belongs to the coordinator while HTTP control/status runs independently.
    with lock(owner.root, "coordinator"):
        with lock(owner.root, "worker"):
            reconcile(owner, key)
        value = api.job(owner, key)
        graph = units(owner, value)
        budget = CatalogueBudget(root, limits)
        validate = [
            u for u in graph if u.startswith("source:") and committed(owner, key, u) is not None
        ]
        remaining = [u for u in graph if committed(owner, key, u) is None]
        final_audit = False
        admission_path = owner.directory / "recovery-admissions" / (key + ".json")
        if (
            admission_path.exists()
            and remaining
            and all(u.startswith("media:") or u == "publish" for u in remaining)
        ):
            admission = record(admission_path)
            if admission["job_id"] != key or admission["remaining"] != remaining:
                raise InputError("D01 finalization recovery graph changed")
            validate = []
            final_audit = True
        for _ in range(256):
            # The 120s deadline bounds each child and each coordinator transaction,
            # not the complete multi-worker request. Aggregate time stays in the pool.
            budget = CatalogueBudget(root, limits)
            state = record(api.state_path(owner, key))
            if state["state"] == "complete":
                return state
            identity = "attempt-" + uuid.uuid4().hex
            owner.reserve_attempt(identity)
            started = time.monotonic()
            running = dict(
                schema_version="d01-state-1",
                job_id=key,
                state="running",
                completed=sum(unit_path(owner, key, u).exists() for u in graph),
                requested=len(graph),
                result=None,
                error=None,
                attempt=identity,
            )
            try:
                owner.publish(
                    budget, owner.directory / "active.json", dict(job_id=key, pid=os.getpid())
                )
                owner.publish(budget, api.state_path(owner, key), running)
                budget.reserve(65536)
                from ..indexing.commands import memory_status
                from ..matchers.runner import peak_memory

                host = memory_status()
                server_memory = peak_memory()
                available = host.get("available_commit_bytes")
                if (
                    available is not None
                    and available < limits["max_working_bytes"] + server_memory
                ):
