"""Read-only adoption of exact C04 units and C01 banks, independent of query choice.

Old guards/declarations are never rewritten. The D01 declaration pins the entire
inherited source map; sources/PCM, memberships and arrays receive fresh D01 proofs.
"""

import numpy as np

from ..evaluation.artifacts import record
from ..indexing import reader
from ..indexing.context import Context as IndexContext
from ..processing import cache, contracts, records
from ..processing.api import graph
from ..processing.context import Context as OldContext
from ..processing.job import output
from ..search import sources
from ..search.contracts import code_identity, grid
from ..search.ranking import distances
from ..storage import InputError, contained, digest


def consumer(owner):
    declaration = record(owner.root / "manifests/application/consumer.json")
    current = code_identity()
    if declaration["code"] != current:
        raise InputError("D01 consumer source drift; explicit scoped declaration required")
    old = record(owner.root / "manifests/processing/consumer.json")
    if (
        old["record_hash"] != owner.protocol["c04_consumer"]
        or any(current.get(k) != h for k, h in old["code"].items())
        or set(current) - set(old["code"]) != set(declaration["new_files"])
    ):
        raise InputError("D01 inherited numerical/coordinator source proof changed")
    return dict(
        declaration_hash=declaration["record_hash"],
        numerical_hash=old["numerical_hash"],
        code_hash=digest(current),
        version="d01-consumer-1",
    )


def inputs(owner):
    old = OldContext(owner.root)
    key = owner.protocol["c04_job"]
    job = record(old.directory / "jobs" / (key + ".json"))
    if job["record_hash"] != key or job["plan"]["record_hash"] != owner.protocol["c04_plan"]:
        raise InputError("D01 pinned C04 job/plan differs")
    plan = old.get(job["plan"], "plans")
    state = record(old.directory / "progress" / (key + ".json"))
    if (
        plan["schema_version"] != "c04-plan-1"
        or plan["units"] != graph(plan["input"])
        or plan["protocol_hash"] != digest(old.protocol)
        or state["result"] is not None
        or len(state["completed"]) != 145
        or old.get(plan["input_ref"], "inputs")["value"] != plan["input"]
    ):
        raise InputError("D01 historical partial chain/schema changed")
    # Strict historical import remains strict. Bank reading below is query independent.
    from ..processing.historical import inspect_inputs

    inspect_inputs(old, plan["input"])
    if len(plan["input"]["sources"]) != 72:
        raise InputError("D01 exact historical population required")
    return old, plan, state


def bank_reader(owner):
    """Fresh bank metadata view, with no historical consumer receipt borrowed.

    Exact C01 plans/memberships are revalidated. Legacy metadata is expanded from
    its pinned record; each consumed array/native/source is audited by adopt().
    This operation does not bind a query and cannot authorize encoding.
    """
    view = IndexContext(owner.root)
    snap = record(view.indexes / "snapshots" / (owner.protocol["snapshot"] + ".json"))
    if snap["record_hash"] != owner.protocol["snapshot"]:
        raise InputError("D01 pinned C01 snapshot changed")
    banks = []
    for key in owner.protocol["primary_banks"]:
        ref = next(r for r in snap["banks"] if r["record_hash"] == key)
        path = contained(owner.root / ref["path"], view.indexes)
        value = record(path)
        if value["record_hash"] != key or value["coverage"]["state"] != "complete":
            raise InputError("D01 incomplete/changed bank")
        if value["schema_version"] == "c01-legacy-reference-1":
            expanded = []
            for u in value["committed"]:
                meta = record(
                    contained(owner.root / u["path"], owner.root / "data/indexes/a06")
                    / "record.json"
                )
                if meta["record_hash"] != u["array_record_hash"] or meta["shape"][0] != u["rows"]:
                    raise InputError("D01 legacy array receipt differs")
                expanded.append({**u, "identity": meta["identity"], "array": meta})
            value = {**value, "committed": expanded}
        else:
            value = reader.read_bank(None, view, path)
        banks.append(dict(value=value, binding=dict(historical_bank_hash=key)))
    if banks[0]["value"]["signals"] != banks[1]["value"]["signals"]:
        raise InputError("D01 banks disagree on exact population/ancestry")
    return view, banks


def old_output(owner, kind, subject):
    old, plan, state = inputs(owner)
    unit = next(u for u in plan["units"] if u["kind"] == kind and u["subject"] == subject)
    return old, plan, output(old, state, unit), state["completed"][unit["unit_id"]]


def adopt(budget, owner, rid):
    old, plan, features, ref = old_output(owner, "features", rid)
    source = next(s for s in plan["input"]["sources"] if s["recording_id"] == rid)
    sources.load(budget, source, context=owner)
    refs = records.expand(features).get("rows", features.get("rows"))
    expected = contracts.native_rows(source, plan["input"]["banks"])
    if [r["native_bounds"] for r in refs] != [list(b) for b in expected]:
        raise InputError("D01 native union differs from complete grid")
    matrix = cache.vectors(budget, old, refs)
    view, banks = bank_reader(owner)
    native = {}
    producers = []
    for bank in banks:
        value = bank["value"]
        if value["signals"][rid]["original"] != source:
            raise InputError("D01 bank source/group differs")
        bounds = []
        for unit in value["committed"]:
            if unit["signal_id"] != rid:
                continue
            arr, passages = reader.rows(budget, view, value, unit)
            for i, p in enumerate(passages):
                b = tuple(p["original_bounds"])
                native[b] = cache.vector_hash(arr[i])
                bounds.append(list(b))
            producers.append(
                dict(
                    bank=bank["binding"]["historical_bank_hash"],
                    array=unit["array"]["record_hash"],
                    membership=digest(passages),
                )
            )
        if bounds != [
            list(b)
            for b in grid(
                source["source"]["sample_count"],
                source["source"]["sample_rate_hz"],
                value["bank"]["identity"]["grid"],
            )
        ]:
            raise InputError("D01 original complete bank membership differs")
    if any(native.get(tuple(r["native_bounds"])) != r["vector_sha256"] for r in refs):
        raise InputError("D01 C04/C01 semantic array mismatch")
    audit = old.get(features["audit"], "consumer-audits")
    if audit["source"] != source or not audit["canonical_pcm_verified"] or audit["new_embeddings"]:
        raise InputError("D01 incompatible C04 source audit")
    proof = dict(
        schema_version="d01-bank-adoption-1",
        source=source,
        old_unit=ref,
        old_audit=features["audit"],
        consumer=consumer(owner),
        membership_digest=digest(refs),
        rows=len(refs),
        producers=producers,
        source_pcm_verified=True,
        new_catalogue_encodes=0,
    )
    return proof, refs, matrix


def validate_scores(raw, refs, matrix, qmatrix, query_result, plan):
    identity = dict(
        version="c04-source-distances-2",
        candidate_rows=len(refs),
        candidate_digest=digest([[r["key"], r["vector_sha256"]] for r in refs]),
        query_features=query_result["feature_hash"],
        numerical_contract=plan["consumer"]["numerical_hash"],
        banks=[b["grid"] for b in plan["input"]["banks"]],
    )
    if raw["schema_version"] != "c04-source-scores-1" or raw["identity"] != identity:
        raise InputError("D01 score dependency identity differs")
    per, means = distances(qmatrix, matrix, "cosine")
    lookup = {r["key"]: i for i, r in enumerate(refs)}
    source = next(
        s for s in plan["input"]["sources"] if contracts.source_key(s) == refs[0]["source_key"]
    )
    offset = {tuple(r["native_bounds"]): i for i, r in enumerate(refs)}
    if len(raw["banks"]) != len(plan["input"]["banks"]):
        raise InputError("D01 score bank population differs")
    for bank, policy in zip(raw["banks"], plan["input"]["banks"], strict=True):
        indices = [
            offset[tuple(b)]
            for b in grid(
                source["source"]["sample_count"], source["source"]["sample_rate_hz"], policy["grid"]
            )
        ]
        best = min(
            indices, key=lambda i: (float(means[i]), *refs[i]["native_bounds"], refs[i]["key"])
        )
        if bank["count"] != len(indices) or bank["baseline"]["key"] != refs[best]["key"]:
            raise InputError("D01 complete bank best/count differs")
        if len(bank["supports"]) != len(qmatrix):
            raise InputError("D01 score query-example population differs")
        for k, support in enumerate(bank["supports"]):
            order = sorted(
                indices, key=lambda i: (float(per[k, i]), *refs[i]["native_bounds"], refs[i]["key"])
            )[:16]
            if [r["key"] for r in support] != [refs[i]["key"] for i in order]:
                raise InputError("D01 exact top support ordering differs")
        for row in [bank["baseline"], *[r for group in bank["supports"] for r in group]]:
            i = lookup[row["key"]]
            if (
                row["bounds"] != refs[i]["native_bounds"]
                or not np.allclose(per[:, i], row["per"], rtol=0, atol=2e-15)
                or abs(float(means[i]) - row["mean"]) > 2e-15
            ):
                raise InputError("D01 historical score/native dependency validation failed")
    return True


class NumericalView:
    """Existing C04 operations, historical row store and D01-only publication.

    The unchanged score reader can reuse a historical locator. New score locators
    are redirected to D01; no method writes or charges a historical owner.
    """

    def __init__(self, owner):
        self.owner = owner
        self.root, self.protocol = owner.root, owner.protocol
        self.directory = owner.root / "data/runs/processing"
        self.query_vectors_cache = {}

    def put(self, *args, **kwargs):
        return self.owner.put(*args, **kwargs)

    def get(self, ref, kind):
        if ref["path"].startswith("data/runs/processing/"):
            return OldContext(self.root).get(ref, kind)
        return self.owner.get(ref, kind)

    def publish(self, budget, path, value, immutable=False):
        relative = contained(path, self.directory / "scores").relative_to(self.directory)
        return self.owner.publish(budget, self.owner.directory / relative, value, immutable)

    def charge(self, *args, **kwargs):
        return self.owner.charge(*args, **kwargs)


def cache_query(view, value, matrix):
    key = digest(
        dict(
            query=value["query"]["record_hash"],
            features=value["feature_hash"],
            saved=value.get("saved_input"),
        )
    )
    view.query_vectors_cache[key] = matrix


def compatible(owner, previous):
    """Only the explicitly pinned D01 path/accounting repair, no unknown drift."""
    current = consumer(owner)
    proof = record(owner.root / "manifests/application/compatibility.json")
    declaration = record(owner.root / "manifests/application/consumer.json")
    if declaration.get("compatibility") != proof["record_hash"]:
        raise InputError("D01 compatibility declaration binding changed")
    if (
        proof["before"] != previous
        or proof["after_code"] != code_identity()
        or current["numerical_hash"] != previous["numerical_hash"]
    ):
        return None
    if proof["changed_inherited_files"] or not proof["numerical_functions_unchanged"]:
        raise InputError("D01 compatibility changes inherited numerical code")
    return proof["record_hash"]

original_sources.application/job.py:
"""Serial bounded worker orchestration, immutable unit commits and protected settlement."""

import json
import os
import subprocess
import time
import uuid

from ..evaluation.artifacts import record
from ..resources import CatalogueBudget
from ..storage import InputError, ResourceError, digest, project_lock
from . import api, history, media, pipeline, queries
from .context import Context, PersistenceError
from .locks import lock


def unit_path(owner, key, unit):
    return owner.directory / "units" / key / (digest(unit) + ".json")


def units(owner, value):
    request = value["identity"]["request"]
    if request["kind"] not in {"search", "validate"}:
        return [request["kind"]]
    old = history.inputs(owner)[1]
    count = len(old["input"]["sources"])
    return [
        "query",
        *[
            "source:" + s["recording_id"]
            for s in sorted(old["input"]["sources"], key=lambda s: s["recording_id"])
        ],
        *["aggregate:" + str(i) for i in range((count * 2 + 7) // 8)],
        "aggregate-final",
        *(["chain"] if request["input"]["query"].get("historical") else []),
        *["media:" + str(i) for i in range(5)],
        "publish",
    ]


def committed(owner, key, unit):
    path = unit_path(owner, key, unit)
    if not path.exists():
        return None
    value = record(path)
    if value["job_id"] != key or value["unit"] != unit:
        raise InputError("D01 committed unit/dependency mismatch")
    return value["output"]


def perform(budget, owner, value, unit, query_cache):
    request = value["identity"]["request"]
    spec, key = request["input"], value["job_id"]
    if request["kind"] == "register":
        from .server import upload_path

        return queries.register(budget, owner, upload_path(owner, spec["upload_id"]), spec["label"])
    if request["kind"] == "copy-reference":
        return queries.copy_historical(budget, owner, spec["revision"])
    if request["kind"] == "metadata-preflight":
        owner.charge(budget, metadata_bytes=128 * 1024)
        return pipeline.metadata_preflight(budget, owner)
    if request["kind"] == "native-qa":
        from .validation import native

        return native(budget, owner, spec)
    if request["kind"] == "save":
        return queries.save(budget, owner, spec)
    if request["kind"] == "rename":
        return queries.rename(budget, owner, spec)
    if request["kind"] == "preview":
        source = media.source_for_asset(owner, spec["asset_id"])
        from ..queries.assets import read_asset

        _, _, samples = read_asset(
            budget, queries.QueryOwner(owner), spec["asset_id"], with_samples=True
        )
        return dict(media=media.cached_clip(budget, owner, source, spec["bounds"], samples))
    if "query" not in query_cache:
        selection = dict(spec["query"])
        previous_query = committed(owner, key, "query")
        if previous_query is not None:
            saved = owner.get(previous_query["query"], "queries")
            selection["materialization"] = saved["materialization"]
        if unit == "query" or unit.startswith("source:"):
            query_cache["query"] = queries.load(budget, owner, selection)
        else:
            # Metadata aggregation and immutable media reuse do not consume query audio.
            query_cache["query"] = (saved, None)
    q, matrix = query_cache["query"]
    if unit == "query":
        return dict(query=owner.put(budget, "queries", q), new_encodes=q["new_encodes"])
    if unit.startswith("source:"):
        return pipeline.source_unit(budget, owner, spec, unit[7:], q, matrix)
    source_results = {
        u[7:]: committed(owner, key, u) for u in units(owner, value) if u.startswith("source:")
    }
    if unit.startswith("aggregate:") or unit == "aggregate-final":
        if "aggregate" not in query_cache:
            query_cache["aggregate"] = pipeline.aggregate(budget, owner, spec, source_results, q)
        result, capture = query_cache["aggregate"]
        if unit == "aggregate-final":
            # All group/source/snapshot refs must exist before publishing this root.
            for path, (kind, data) in capture.records.items():
                ref = dict(path=path, record_hash=__import__("pathlib").Path(path).stem)
                owner.get(ref, kind)
            return dict(aggregate=owner.put(budget, "aggregates", result))
        i = int(unit.split(":")[1]) * 8
        items = sorted(capture.records.items())
        # Sources/snapshot are small shared records. Groups are the bounded subunits.
        groups = [(path, item) for path, item in items if item[0] == "group-results"]
        for path, (kind, data) in [(p, v) for p, v in items if v[0] != "group-results"] + groups[
            i : i + 8
        ]:
            owner.put(budget, kind, data)
        return dict(groups=[p for p, _ in groups[i : i + 8]], new_encodes=0)
    aggregate = owner.get(committed(owner, key, "aggregate-final")["aggregate"], "aggregates")
    if unit == "chain":
        return dict(
            chain=owner.put(
                budget, "chains", pipeline.audit_chain(budget, owner, spec, aggregate, q)
            )
        )
    if unit.startswith("media:"):
        # C03 experimental rendering is explicitly separate from legacy/event cards.
        if spec["arm"] == "historical-refinement":
            return dict(cards=[], historical=True)
        return dict(cards=media.cards(budget, owner, aggregate, int(unit[6:]) * 2, 2))
    if unit == "publish":
        cards = [c for i in range(5) for c in committed(owner, key, "media:" + str(i))["cards"]]
        chain = committed(owner, key, "chain") if spec["query"].get("historical") else None
        return dict(
            result=owner.put(
                budget,
                "results",
                dict(
                    schema_version="d01-result-1",
                    state="complete",
                    job_id=key,
                    query=committed(owner, key, "query")["query"],
                    selection=spec["query"],
                    policy=spec["arm"],
                    consumer=value["consumer"],
                    **aggregate,
                    cards=cards,
                    chain=chain,
                    historical_view=spec["arm"] == "historical-refinement",
                    resource_owner="data/runs/application/pool.json",
                    historical_c04_state="partial 145/148",
                    new_catalogue_encodes=0,
                    defaults=dict(audio="original", arm="legacy-mean", pitch="off"),
                ),
            )
        )
    raise InputError("D01 unknown executable unit")


def worker(request):
    from ..matchers.job import offline_network
    from ..matchers.runner import memory_check

    owner = Context(__import__("pathlib").Path(request["root"]), request["job_id"])
    budget = CatalogueBudget(owner.root, request["limits"])
    key = request["job_id"]
    with project_lock(owner.root), lock(owner.root, "worker"), offline_network():
        value = api.job(owner, key)
        if history.consumer(owner) != value["consumer"] and not history.compatible(
            owner, value["consumer"]
        ):
            raise InputError("D01 request consumer changed; declare scoped compatibility")
        graph = units(owner, value)
        cache, done, encodes = {}, [], 0
        if request.get("finalization_audit"):
            from .validation import finalization

            receipt = finalization(budget, owner, key)
            return dict(
                status="ok",
                state="validated-finalization",
                completed=[],
                new_encodes=0,
                receipt=receipt,
                peak_working_bytes=memory_check(budget),
            )
        if request.get("validate_units"):
            spec = value["identity"]["request"]["input"]
            saved = owner.get(committed(owner, key, "query")["query"], "queries")
            q, matrix = queries.load(
                budget, owner, {**spec["query"], "materialization": saved["materialization"]}
            )
            for unit in request["validate_units"]:
                cancel = owner.directory / "cancels" / (key + ".json")
                if cancel.exists() and not record(cancel).get("resumed", False):
                    return dict(status="ok", state="cancelled", completed=[], new_encodes=0)
                answer = pipeline.source_unit(budget, owner, spec, unit[7:], q, matrix)
                validate_resumed(owner, budget, unit, committed(owner, key, unit), answer)
            return dict(
                status="ok",
                state="validated",
                completed=[],
                new_encodes=0,
                peak_working_bytes=memory_check(budget),
            )
        # Four useful units maximum. The worker owns one lazy model and query matrix.
        for unit in graph:
            if committed(owner, key, unit) is not None:
                continue
            cancel = owner.directory / "cancels" / (key + ".json")
            if cancel.exists() and not record(cancel).get("resumed", False):
                return dict(
                    status="ok",
                    state="cancelled",
                    completed=done,
                    new_encodes=encodes,
                    peak_working_bytes=memory_check(budget),
                )
            answer = perform(budget, owner, value, unit, cache)
            owner.publish(
                budget,
                unit_path(owner, key, unit),
                dict(job_id=key, unit=unit, output=answer),
                immutable=True,
            )
            done.append(unit)
            encodes += answer.get("new_encodes", 0)
            if len(done) >= 4 or time.monotonic() - budget.started > 60:
                break
        count = sum(unit_path(owner, key, u).exists() for u in graph)
        return dict(
            status="ok",
            state="complete" if count == len(graph) else "in_progress",
            completed=done,
            new_encodes=encodes,
            peak_working_bytes=memory_check(budget),
        )


def execute(owner, key, limits, validate_units=None, finalization_audit=False):
    from ..processing.runner import python_command

    environment = os.environ.copy()
    environment.update(
        OMP_NUM_THREADS="1", OPENBLAS_NUM_THREADS="1", MKL_NUM_THREADS="1", PYTHONIOENCODING="utf-8"
    )
    command = python_command(owner.root / "scripts/application-worker.py")
    request = dict(root=str(owner.root), job_id=key, limits=limits)
    if validate_units:
        request["validate_units"] = validate_units
    if finalization_audit:
        request["finalization_audit"] = True
    try:
        completed = subprocess.run(
            command,
            input=json.dumps(request),
            capture_output=True,
            text=True,
            encoding="utf-8",
            timeout=limits["max_seconds"],
            env=environment,
            check=False,
        )
    except subprocess.TimeoutExpired:
        return dict(
            status="failed",
            error_type="ResourceError",
            error="D01 actual worker exceeded 120s and stopped; retain reservation",
            uncertain=True,
        )
    try:
        result = json.loads(completed.stdout)
    except ValueError:
        return dict(
            status="failed",
            error_type="WorkerExit",
            error="D01 worker exited without a durable answer: " + completed.stderr[-1500:],
            uncertain=True,
        )
    return result


def reconcile(owner, key):
    """Only after exclusive coordinator/worker locks. Unobservable time stays charged."""
    pool = owner.pool()
    for identity, slot in pool["attempts"].items():
        if not slot["settled"]:
            previous_key = slot.get("job_id") or key
            previous = record(api.state_path(owner, previous_key))
            previous.update(
                state="interrupted",
                error=dict(
                    step="recovery",
                    message="Owned process stopped without settlement; full reservation retained",
                ),
            )
            owner.terminal(identity, api.state_path(owner, previous_key), previous, uncertain=True)


def _run(root, limits, key):
    owner = Context(root, key)
    # This lock belongs to the coordinator while HTTP control/status runs independently.
    with lock(owner.root, "coordinator"):
        with lock(owner.root, "worker"):
            reconcile(owner, key)
        value = api.job(owner, key)
        graph = units(owner, value)
        budget = CatalogueBudget(root, limits)
        validate = [
            u for u in graph if u.startswith("source:") and committed(owner, key, u) is not None
        ]
        remaining = [u for u in graph if committed(owner, key, u) is None]
        final_audit = False
        admission_path = owner.directory / "recovery-admissions" / (key + ".json")
        if (
            admission_path.exists()
            and remaining
            and all(u.startswith("media:") or u == "publish" for u in remaining)
        ):
            admission = record(admission_path)
            if admission["job_id"] != key or admission["remaining"] != remaining:
                raise InputError("D01 finalization recovery graph changed")
            validate = []
            final_audit = True
        for _ in range(256):
            # The 120s deadline bounds each child and each coordinator transaction,
            # not the complete multi-worker request. Aggregate time stays in the pool.
            budget = CatalogueBudget(root, limits)
            state = record(api.state_path(owner, key))
            if state["state"] == "complete":
                return state
            identity = "attempt-" + uuid.uuid4().hex
            owner.reserve_attempt(identity)
            started = time.monotonic()
            running = dict(
                schema_version="d01-state-1",
                job_id=key,
                state="running",
                completed=sum(unit_path(owner, key, u).exists() for u in graph),
                requested=len(graph),
                result=None,
                error=None,
                attempt=identity,
            )
            try:
                owner.publish(
                    budget, owner.directory / "active.json", dict(job_id=key, pid=os.getpid())
                )
                owner.publish(budget, api.state_path(owner, key), running)
                budget.reserve(65536)
                from ..indexing.commands import memory_status
                from ..matchers.runner import peak_memory

                host = memory_status()
                server_memory = peak_memory()
                available = host.get("available_commit_bytes")
                if (
                    available is not None
                    and available < limits["max_working_bytes"] + server_memory
                ):
                    raise ResourceError(
                        "D01 insufficient available commit for worker plus server overlap"
                    )
                answer = execute(
                    owner, key, {**limits, "max_seconds": 120}, validate[:4], final_audit
                )
                budget = CatalogueBudget(root, limits)
                answer["server_peak_working_bytes"] = server_memory
                answer["overlap_peak_bound"] = server_memory + answer.get("peak_working_bytes", 0)
                if answer.get("state") == "validated":
                    del validate[:4]
                    answer["state"] = "in_progress"
                if answer.get("state") == "validated-finalization":
                    final_audit = False
                    answer["state"] = "in_progress"
                count = sum(unit_path(owner, key, u).exists() for u in graph)
                outcome = answer.get(
                    "state", "blocked" if answer.get("error_type") == "ResourceError" else "failed"
                )
                if answer["status"] == "failed":
                    outcome = "blocked" if answer.get("error_type") == "ResourceError" else "failed"
                result = (
                    committed(owner, key, "publish")["result"]
                    if outcome == "complete" and request_search(value)
                    else None
                )
                if outcome == "complete" and not request_search(value):
                    result = owner.put(
                        budget,
                        "results",
                        dict(
                            schema_version="d01-operation-result-1",
                            state="complete",
                            job_id=key,
                            operation=value["identity"]["request"]["kind"],
                            output=committed(owner, key, graph[0]),
                        ),
                    )
                terminal = {
                    **running,
                    "state": outcome,
                    "completed": count,
                    "result": result,
                    "error": None
                    if answer["status"] == "ok"
                    else dict(
                        step="worker",
                        error_type=answer.get("error_type"),
                        message=answer.get("error"),
                    ),
                    "worker_evidence": answer,
                }
                if outcome == "complete" and request_search(value):
                    owner.publish(
                        budget,
                        owner.directory / "last-complete.json",
                        dict(job_id=key, result=result),
                    )
                owner.terminal(
                    identity,
                    api.state_path(owner, key),
                    terminal,
                    elapsed=time.monotonic() - started,
                    uncertain=answer.get("uncertain", False),
                )
            except PersistenceError:
                raise
            except (InputError, OSError, ValueError, RuntimeError, MemoryError) as exc:
                terminal = {
                    **running,
                    "state": "blocked" if isinstance(exc, ResourceError) else "failed",
                    "error": dict(
                        step="coordinator", error_type=type(exc).__name__, message=str(exc)
                    ),
                }
                owner.terminal(
                    identity,
                    api.state_path(owner, key),
                    terminal,
                    elapsed=time.monotonic() - started,
                )
                return terminal
            if terminal["state"] != "in_progress":
                if terminal["state"] == "complete":
                    owner.release(key)
                return terminal
        raise ResourceError("D01 finite dispatch limit reached")


def request_search(value):
    return value["identity"]["request"]["kind"] in {"search", "validate"}


def validate_resumed(owner, budget, unit, previous, current):
    """Fresh consumer proof is distinct from unchanged semantic source/score output."""
    before = owner.get(previous["proof"], "adoptions")
    after = owner.get(current["proof"], "adoptions")
    prior = before["consumer"]
    archive = owner.root / "manifests/application/consumers" / (prior["declaration_hash"] + ".json")
    active = history.consumer(owner)
    if prior != active:
        declaration = record(archive)
        if (
            declaration["record_hash"] != prior["declaration_hash"]
            or digest(declaration["code"]) != prior["code_hash"]
            or declaration["numerical_hash"] != active["numerical_hash"]
        ):
            raise InputError("D01 resumed producer/consumer proof is unknown")

    def fields(p):
        return {k: v for k, v in p.items() if k not in {"record_hash", "consumer"}}

    if previous["scores"] != current["scores"] or fields(before) != fields(after):
        raise InputError("D01 resumed source/score semantic dependency differs")
    owner.put(
        budget,
        "resume-audits",
        dict(
            unit=unit,
            previous=previous["proof"],
            fresh=current["proof"],
            semantic_source_scores_unchanged=True,
        ),
    )


def run(root, limits, key):
    try:
        return _run(root, limits, key)
    except PersistenceError:
        raise
    except (InputError, OSError, ValueError, RuntimeError) as exc:
        from .locks import active

        if active(root, "coordinator") or active(root, "worker"):
            raise
        owner = Context(root, key)
        previous = record(api.state_path(owner, key))
        slot = "admission-" + uuid.uuid4().hex
        owner.reserve_attempt(slot, seconds=0)
        terminal = {
            **previous,
            "state": "blocked" if isinstance(exc, ResourceError) else "failed",
            "error": dict(step="admission", message=str(exc), error_type=type(exc).__name__),
        }
        owner.terminal(slot, api.state_path(owner, key), terminal, elapsed=0)
        return terminal

